      function renderJobGuide(){const job=activeJob(),ac=activeCandidates(),analysis=hybridState.analyses?.[activeJobId],steps=[{label:'Define criteria',detail:'Set the job requirements',done:Boolean(job?.criteria?.length),page:'criteria'},{label:'Add candidates',detail:'Build the candidate pool',done:ac.length>0,page:'candidates'},{label:'Choose a benchmark',detail:'Mark a reference candidate',done:ac.some(c=>c.benchmark),page:'benchmarks'},{label:'Record manager feedback',detail:'Capture a real hiring signal',done:feedback.some(f=>f.jobId===activeJobId),page:'feedback'},{label:'Analyze hiring patterns',detail:'Find recurring evidence',done:Boolean(analysis),page:'insights'},{label:'Update evaluations',detail:'Review proposed score changes',done:Boolean(analysis?.reevaluation_proposals?.some(x=>x.status==='applied')),page:'insights'}],complete=steps.filter(x=>x.done).length;root.querySelector('#jobGuideProgress').textContent=`${complete} of ${steps.length} complete`;root.querySelector('#jobGuideProgress').className='rf-pill '+(complete===steps.length?'rf-green':'rf-blue');const wrap=root.querySelector('#jobGuideSteps');wrap.innerHTML=steps.map((step,index)=>`<button class="rf-guide-step ${step.done?'done':''}" type="button" data-guide-page="${step.page}"><span class="rf-guide-check">${step.done?'✓':index+1}</span><span class="rf-guide-copy"><strong>${step.label}</strong><small>${step.done?'Complete':step.detail}</small></span></button>`).join('');wrap.querySelectorAll('[data-guide-page]').forEach(button=>button.addEventListener('click',()=>showPage(button.dataset.guidePage)));renderAnalysisFlow()}
      function renderAnalysisFlow(){const result=hybridState.analyses?.[activeJobId],button=root.querySelector('#reevaluateCandidates'),stepOne=root.querySelector('#analysisStepOne'),stepTwo=root.querySelector('#analysisStepTwo');if(!button||!stepOne||!stepTwo)return;const analyzed=Boolean(result),reviewed=Boolean(result?.reevaluation_proposals?.length);button.disabled=!analyzed||reevaluationRunning;button.title=analyzed?'Create reviewable candidate score proposals':'Analyze hiring patterns first';stepOne.classList.toggle('complete',analyzed);stepTwo.classList.toggle('complete',reviewed)}
      function renderMetrics(){const list=ranked();const job=activeJob();root.querySelector('.rf-brand span').textContent=job.title;root.querySelector('#page-dashboard .rf-top p').textContent='Active job: '+job.title+(job.client?' · '+job.client:'');if(list.length){root.querySelector('#topName').textContent=list[0].short;root.querySelector('#topScore').textContent=list[0].managerScore.toFixed(1)+'/10 manager fit · '+list[0].rec;root.querySelector('#avgScore').textContent=(list.reduce((s,c)=>s+c.managerScore,0)/list.length).toFixed(1)}else{root.querySelector('#topName').textContent='—';root.querySelector('#topScore').textContent='No candidates yet';root.querySelector('#avgScore').textContent='—'}const interviews=list.filter(c=>c.rec==='Interview');root.querySelector('#candidateCount').textContent=list.length;root.querySelector('#interviewCount').textContent=interviews.length;root.querySelector('#interviewNames').textContent=interviews.length?interviews.map(c=>c.short).join(', '):'No interview recommendations yet';renderDashboardPanels();renderJobGuide()}
      function renderDashboardPanels(){const ac=activeCandidates(),job=activeJob(),list=ranked();const stageOrder=['Sourced','Screened','Submitted','Interviewing','Offer','Hired'];const total=Math.max(ac.length,1);const pipeline=root.querySelector('#dashboardPipelineOverview');pipeline.innerHTML='<div class="rf-funnel">'+stageOrder.map((s,i)=>{const n=ac.filter(c=>c.stage===s).length;const pct=Math.round(n/total*100);const width=Math.max(34,100-i*11);return `<div class="rf-funnel-row"><div class="rf-funnel-bar" style="width:${width}%">${n}</div><div class="rf-funnel-label">${s}</div><div class="rf-funnel-pct">${pct}%</div></div>`}).join('')+'</div><div class="rf-conversion">Conversion rate: <strong>'+((ac.filter(c=>c.stage==='Hired').length/total)*100).toFixed(ac.length?0:0)+'%</strong></div>';const buckets=[{label:'8.0 – 10',min:8,max:10,color:'#34c77b'},{label:'6.0 – 7.9',min:6,max:7.99,color:'#3478dd'},{label:'4.0 – 5.9',min:4,max:5.99,color:'#6644ca'},{label:'2.0 – 3.9',min:2,max:3.99,color:'#8b47b9'},{label:'0 – 1.9',min:0,max:1.99,color:'#bc5b7a'}];const counts=buckets.map(b=>ac.filter(c=>c.managerScore>=b.min&&c.managerScore<=b.max).length);const fit=root.querySelector('#dashboardFitDistribution');fit.innerHTML='<div class="rf-donut-wrap"><div class="rf-donut"></div><div class="rf-legend">'+buckets.map((b,i)=>`<div class="rf-legend-row"><span class="rf-legend-dot" style="background:${b.color}"></span><span>${b.label}</span><span>${counts[i]} (${Math.round(counts[i]/total*100)}%)</span></div>`).join('')+'</div></div><div class="rf-conversion">Average Fit Score: <strong>'+(ac.length?(ac.reduce((s,c)=>s+c.managerScore,0)/ac.length).toFixed(1):'—')+'</strong></div>';const events=[];feedback.filter(f=>ac.some(c=>c.short===f.candidate)).slice(-4).forEach(f=>events.push({icon:'✓',text:`Manager feedback added for <strong>${f.candidate}</strong>`,time:'recent'}));interviewOutcomes.filter(o=>o.jobId===activeJobId).slice(-4).forEach(o=>events.push({icon:'▣',text:`Interview outcome added for <strong>${o.candidate}</strong>`,time:'recent'}));ac.slice().sort((a,b)=>b.updatedAt-a.updatedAt).slice(0,4).forEach(c=>events.push({icon:'◉',text:`Candidate <strong>${c.short}</strong> moved to ${c.stage}`,time:'updated'}));root.querySelector('#dashboardActivity').innerHTML='<div class="rf-activity">'+events.slice(-5).reverse().map(e=>`<div class="rf-activity-row"><div class="rf-activity-icon">${e.icon}</div><div class="rf-activity-copy">${e.text}</div><div class="rf-activity-time">${e.time}</div></div>`).join('')+'</div>';const top=root.querySelector('#dashboardTopCandidates');top.innerHTML=list.length?'<table class="rf-top-table"><thead><tr><th>Candidate</th><th>Fit Score</th><th>Assessment</th><th>Stage</th></tr></thead><tbody>'+list.slice(0,5).map(c=>`<tr class="rf-row" data-name="${c.name.replace(/"/g,'&quot;')}"><td>${c.short}${c.stage==='Hired'?' 🙂':''}</td><td>${c.managerScore.toFixed(1)}</td><td class="${c.managerScore>=8?'rf-fit-good':c.managerScore>=6?'rf-fit-mid':'rf-fit-warn'}">${c.rec}</td><td><span class="rf-pill rf-blue">${c.stage}</span></td></tr>`).join('')+'</tbody></table>':'<div class="rf-note">No candidates yet for this search.</div>';top.querySelectorAll('.rf-row').forEach(r=>r.addEventListener('click',()=>openDetail(r.dataset.name)));const summary=root.querySelector('#dashboardSearchSummary');summary.innerHTML='<div class="rf-summary-list"><div class="rf-summary-row"><span>Job Title</span><span>'+job.title+'</span></div><div class="rf-summary-row"><span>Client</span><span>'+(job.client||'—')+'</span></div><div class="rf-summary-row"><span>Candidates</span><span>'+ac.length+'</span></div><div class="rf-summary-row"><span>Benchmarks</span><span>'+ac.filter(c=>c.benchmark).length+'</span></div><div class="rf-summary-row"><span>Criteria</span><span>'+(job.criteria||[]).length+'</span></div><div class="rf-summary-row"><span>Knockout Rules</span><span>'+(job.knockouts||[]).length+'</span></div></div>'}
      function renderPipeline(){const stages=['Sourced','Screened','Submitted','Interviewing','Offer','Hired','Rejected','Withdrew'];const board=root.querySelector('#pipelineBoard');board.innerHTML=stages.map(s=>`<div class="rf-stage"><h4>${s} · ${activeCandidates().filter(c=>c.stage===s).length}</h4>${activeCandidates().filter(c=>c.stage===s).map(c=>`<div class="rf-stageitem" data-pipeline-name="${c.name.replace(/"/g,'&quot;')}"><strong>${escapeHTML(c.short)}${c.stage==='Hired'?' 🙂':''}</strong><div class="rf-sub">${c.managerScore.toFixed(1)}/10 · ${escapeHTML(c.rec)}</div></div>`).join('')||'<div class="rf-sub">No candidates</div>'}</div>`).join('');board.querySelectorAll('[data-pipeline-name]').forEach(x=>x.addEventListener('click',()=>openDetail(x.dataset.pipelineName)))}
      function updateCompareStatus(){const ids=['compare1','compare2','compare3','compare4'],values=ids.map(id=>root.querySelector('#'+id).value).filter(Boolean),count=new Set(values).size;ids.forEach(id=>{const select=root.querySelector('#'+id);[...select.options].forEach(option=>{option.disabled=Boolean(option.value&&option.value!==select.value&&values.includes(option.value))})});root.querySelector('#compareSelectionStatus').textContent=count?`${count} candidate${count===1?'':'s'} selected`:'No candidates selected';root.querySelector('#runCompare').disabled=count<2}
