      function renderComparison(){const selected=['compare1','compare2','compare3','compare4'].map(id=>root.querySelector('#'+id).value).filter(Boolean).map(n=>activeCandidates().find(c=>c.name===n)).filter(Boolean);const wrap=root.querySelector('#compareResults');if(selected.length<2){wrap.innerHTML='<div class="rf-compare-empty"><div><div class="rf-compare-empty-icon">◎</div><strong>Select at least two candidates</strong><p class="rf-sub">A side-by-side comparison needs two or more profiles.</p></div></div>';return}const rows=[['Candidate',...selected.map(c=>'<strong>'+c.short+'</strong>')],['Overall Fit',...selected.map(c=>c.managerScore.toFixed(1)+'/10')],['JD Fit',...selected.map(c=>c.jdScore.toFixed(1)+'/10')],['Stage',...selected.map(c=>c.stage)],['Recommendation',...selected.map(c=>c.rec)],['Strengths',...selected.map(c=>(c.strengths||[]).slice(0,3).join(' • '))],['Risks',...selected.map(c=>(c.concerns||[]).slice(0,3).join(' • '))],['Knockouts',...selected.map(c=>knockoutRisks(c).join(' • ')||'None')],['Interview Outcome',...selected.map(c=>{const o=interviewOutcomes.filter(x=>x.jobId===activeJobId&&x.candidate===c.short).slice(-1)[0];return o?o.decision:'—'})]];wrap.innerHTML='<div class="rf-comparegrid" style="grid-template-columns:180px repeat('+selected.length+',minmax(200px,1fr))">'+rows.flatMap((r,row)=>r.map((x,col)=>`<div class="${col===0?'rf-compare-label':''} ${row===0?'rf-compare-head':''}">${x}</div>`)).join('')+'</div>'}
