      function applyReevaluation(index,{quiet=false}={}){const result=hybridState.analyses?.[activeJobId],proposal=result?.reevaluation_proposals?.[index],candidate=candidateForRef(proposal?.candidateId);if(!proposal||proposal.status!=='pending'||!candidate)return;if(!proposal.contextSignature||proposal.contextSignature!==evaluationSignature(candidate)){showToast('This proposal is outdated. Update Candidate Evaluations again.','error');return}const audit={previousScore:Number(candidate.managerScore),newScore:Number(proposal.proposedScore),previousRecommendation:candidate.rec,newRecommendation:proposal.proposedRecommendation,reasons:proposal.reasons,appliedAt:Date.now()};const history=[...(candidate.aiReview?.history||[]),audit].slice(-20);candidate.aiReview={verdict:'Needs Adjustment',correctedScore:audit.newScore,reasons:['Hybrid re-evaluation'],notes:proposal.reasons.join(' · '),source:'hybrid_reevaluation',priorCorrection:candidate.aiReview?.source==='hybrid_reevaluation'?candidate.aiReview.priorCorrection:candidate.aiReview,contextSignature:proposal.contextSignature,model:proposal.model,history,createdAt:audit.appliedAt};candidate.updatedAt=audit.appliedAt;proposal.status='applied';proposal.appliedAt=audit.appliedAt;recalibrateCandidate(candidate);saveState();saveHybridState();renderReevaluationResults();recalibrateAll();if(!quiet)showToast(`${candidate.short} updated to ${candidate.managerScore.toFixed(1)}/10.`)}
